  async function renameNote(n){menu.replaceChildren();const input=document.createElement('input');input.value=n.title||'Untitled';input.setAttribute('aria-label','Note name');input.maxLength=160;const apply=async()=>{const title=input.value.trim();if(!title)return;closeMenu();if(n.id===core.activeId())core.current();n.title=title;if(n.id===core.activeId())$('#note-title').textContent=title;await core.save(n);renderList()};menu.append(input,button('Save name',apply));input.onkeydown=e=>{if(e.key==='Enter')apply();if(e.key==='Escape')closeMenu()};input.focus();input.select()}
