  function noteRow(n,nested=false,seen=new Set()){seen=new Set(seen);seen.add(n.id);const row=document.createElement('div');row.className='sidebar-page-row'+(nested?' nested-page':'');row.dataset.noteId=n.id;const open=button(n.title||'Untitled',()=>openNote(n.id));open.className='note-row'+(n.id===core.activeId()?' current':'');const dot=document.createElement('span');dot.className='note-dot';open.prepend(dot);const more=button('',()=>noteMenu(n,more),'more');more.className='page-more';more.setAttribute('aria-label','Options for '+(n.title||'Untitled'));more.title='Rename, move and more';const toggle=button(expanded.has(n.id)?'▾':'▸',()=>{expanded.has(n.id)?expanded.delete(n.id):expanded.add(n.id);renderList()});toggle.className='folder-toggle';toggle.setAttribute('aria-label','Expand '+(n.title||'Untitled'));toggle.setAttribute('aria-expanded',String(expanded.has(n.id)));const add=button('+',()=>createSubpage(n.id));add.className='page-add';add.setAttribute('aria-label','New subpage in '+(n.title||'Untitled'));row.append(toggle,open,add,more);row.addEventListener('contextmenu',e=>{e.preventDefault();noteMenu(n,more)});const group=document.createElement('div');group.className='sidebar-page-group';group.append(row);if(expanded.has(n.id)){const sub=document.createElement('div');sub.className='folder-children';for(const child of children(n.id))if(!seen.has(child.id))sub.append(noteRow(child,true,seen));group.append(sub)}return group}
  function folderRow(f){const group=document.createElement('div');group.className='sidebar-folder';group.dataset.folderId=f.id;const row=document.createElement('div');row.className='sidebar-page-row folder-row';const toggle=button(expanded.has(f.id)?'▾':'▸',()=>{expanded.has(f.id)?expanded.delete(f.id):expanded.add(f.id);renderList()});toggle.className='folder-toggle';toggle.setAttribute('aria-label','Expand '+f.folderName);toggle.setAttribute('aria-expanded',String(expanded.has(f.id)));const open=button(f.folderName||'Untitled folder',()=>{expanded.add(f.id);navigate('folder',f.id)},'folder');open.className='folder-open';open.classList.toggle('active',view==='folder'&&folderId===f.id);const add=button('+',async()=>{closeMenu();view='folder';folderId=f.id;expanded.add(f.id);await createNote()});add.className='page-add';add.setAttribute('aria-label','New note in '+f.folderName);const more=button('',()=>{openMenu(more);menu.append(button('Rename',()=>{closeMenu();renameFolder(f)}),button('Delete folder',()=>{closeMenu();deleteFolder(f)}))},'more');more.className='page-more';more.setAttribute('aria-label','Options for '+f.folderName);row.append(toggle,open,add,more);group.append(row);if(expanded.has(f.id)){const children=document.createElement('div');children.className='folder-children';for(const n of noteItems().filter(n=>n.folderId===f.id&&!n.archivedAt&&!n.trashedAt))children.append(noteRow(n,true));if(!children.children.length){const empty=document.createElement('small');empty.className='tree-empty';empty.textContent='No pages inside';children.append(empty)}group.append(children)}return group}
  const binInfo=document.createElement('div');binInfo.className='bin-info';binInfo.hidden=true;$('#note-view .rule').before(binInfo);
