  window.addEventListener('eye-mode-changed',event=>{if(event.detail?.enabled&&view==='threads')navigate('all')});
  function navigate(next,id=null){if(next==='movies')window.scrollTo({top:0,behavior:'instant'});if(threadDrag)finishThreadDrag(false);closeMenu();readLocation();pendingLocation=null;view=next;folderId=id;core.showHome();activeNav();rememberLocation();window.setMobileSidebar?.(false)}
  const cover=$('#note-cover'),coverStage=$('#note-cover-stage'),coverDots=$('#note-cover-dots'),coverInputs=$('#note-cover-inputs'),coverStatus=$('#note-cover-status');let coverIndex=0,coverLoadError=false;
  function coverUrl(raw){try{const url=new URL(raw);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?url.href:null}catch{return null}}
  function coverItems(n=core.note()){const list=Array.isArray(n?.coverMedia)?n.coverMedia:(n?.coverUrl?[n.coverUrl]:[]);return list.map(value=>typeof value==='string'?{url:value}:value).filter(x=>coverUrl(x?.url)).map(x=>({url:coverUrl(x.url),type:x.type==='video'||x.type==='image'?x.type:/\.(mp4|webm|ogv|mov|m4v)(?:$|[?#])/i.test(x.url)?'video':'image'}))}
  function renderCover(){const list=coverItems(),visible=list.length&&!core.locked()&&!$('#note-view').hidden;if(!visible){cover.hidden=true;coverStage.replaceChildren();coverDots.replaceChildren();return}coverIndex=((coverIndex%list.length)+list.length)%list.length;cover.hidden=false;const item=list[coverIndex];if(coverStage.dataset.url!==item.url){coverLoadError=false;coverStage.dataset.url=item.url;coverStage.replaceChildren();const media=document.createElement(item.type);media.src=item.url;media.alt='';media.referrerPolicy='no-referrer';media.decoding='async';if(item.type==='video'){media.controls=true;media.playsInline=true;media.preload='metadata'}else media.loading='lazy';media.onerror=()=>{coverLoadError=true;const fallback=document.createElement('div');fallback.className='note-cover-fallback';const message=document.createElement('span');message.textContent='This media link could not be opened. It may be private or expired.';const link=document.createElement('a');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open original media';fallback.append(message,link);media.replaceWith(fallback);coverStatus.textContent='Media URL saved, but it could not be loaded. Use a direct URL that is accessible in your browser.'};coverStage.append(media)}coverDots.hidden=list.length<2;coverDots.replaceChildren();if(list.length>1)list.forEach((_,i)=>{const dot=document.createElement('button');dot.type='button';dot.className='note-cover-dot';dot.setAttribute('aria-label','Show cover '+(i+1)+' of '+list.length);dot.setAttribute('aria-current',String(i===coverIndex));dot.onclick=()=>{coverIndex=i;coverStage.dataset.url='';renderCover()};coverDots.append(dot)})}
  function coverEmptyState(){if(coverInputs.children.length)return;const empty=document.createElement('div');empty.className='note-cover-empty';empty.textContent='No media URLs added yet. Use + Add URL to get started.';coverInputs.append(empty)}
  function addCoverInput(value=''){const rows=coverInputs.querySelectorAll('.note-cover-input-row');if(rows.length>=20){coverStatus.textContent='You can add up to 20 cover URLs.';return null}coverInputs.querySelector('.note-cover-empty')?.remove();const row=document.createElement('div');row.className='note-cover-input-row';const index=rows.length+1;const input=document.createElement('input');input.type='url';input.placeholder='https://example.com/image.jpg or video.mp4';input.autocomplete='url';input.setAttribute('aria-label','Cover media URL '+index);input.value=value;const remove=button('×',()=>{row.remove();[...coverInputs.querySelectorAll('.note-cover-input-row input')].forEach((field,i)=>field.setAttribute('aria-label','Cover media URL '+(i+1)));coverEmptyState()},'Remove URL');remove.className='note-cover-remove';row.append(input,remove);coverInputs.append(row);return input}
