    const upcoming=Array.from({length:13-currentMonth},(_,i)=>currentMonth+i);
    const past=Array.from({length:currentMonth-1},(_,i)=>i+1).filter(index=>pages.has(index));
    $('#crumb-title').textContent='Monthly goals';
    $('.home-heading h1').textContent='Months';
    $('.home-heading p').textContent='Start with this month. Keep your goals as simple as you like.';
    $('.home-section-head h2').textContent='This month & ahead';
