      const preview=document.createElement('span');preview.className='month-card-preview';
      preview.textContent=note?(note.blocks||[]).map(b=>b.text||b.bodyText||'').filter(Boolean).join(' · ').slice(0,100)||'Your page is ready for thoughts and goals.':'A fresh space for your goals.';
      const foot=document.createElement('span');foot.className='month-card-foot';foot.textContent=note?'Continue writing':'Start writing';
      const arrow=document.createElement('span');arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';foot.append(arrow);
