  function insertDateMention(keyword,range=mentionRange,now=new Date()){if(!range||!core.editor.contains(range.commonAncestorContainer))return false;const date=new Date(now);if(keyword==='yesterday')date.setDate(date.getDate()-1);else if(keyword==='tomorrow')date.setDate(date.getDate()+1);else if(!['today','now'].includes(keyword))return false;const value=keyword==='now'?date.toISOString():dateKey(date),pill=document.createElement('span');pill.dataset.dateMention=value;pill.dataset.dateKind=keyword;pill.contentEditable='false';const options=keyword==='now'?{hour:'numeric',minute:'2-digit'}:{month:'short',day:'numeric',year:'numeric'};pill.textContent=new Intl.DateTimeFormat(undefined,options).format(date);range.deleteContents();range.insertNode(pill);const spacer=document.createTextNode(' ');pill.after(spacer);range.setStart(spacer,1);range.collapse(true);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);closeMentions();(pill.closest('[contenteditable=true]')||core.editor).dispatchEvent(new InputEvent('input',{bubbles:true}));return value}

  function insertThreadMention(thread,range=mentionRange){if(!isNormalPage(core.note())||!thread||thread.kind!=='thread'||thread.trashedAt||thread.archivedAt||core.locked()||!range||!core.editor.contains(range.commonAncestorContainer))return false;const day=dateKey(new Date(),thread.threadZone),pill=document.createElement('span');pill.dataset.threadMention=thread.id;pill.dataset.threadDate=day;pill.contentEditable='false';pill.textContent='@threads-'+(thread.title||'Untitled');range.deleteContents();range.insertNode(pill);const spacer=document.createTextNode(' ');pill.after(spacer);range.setStart(spacer,1);range.collapse(true);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);closeMentions();(pill.closest('[contenteditable=true]')||core.editor).dispatchEvent(new InputEvent('input',{bubbles:true}));toggleThread(thread.id,day,true).then(()=>toast('Ticked '+(thread.title||'Untitled')+' for today')).catch(e=>toast('Could not tick thread: '+e.message));return true}


  async function createMentionSubpage(title,range=mentionRange){const parent=core.note();if(!parent||parent.trashedAt||core.locked()||!range||!core.editor.contains(range.commonAncestorContainer))return;const n={id:uuid(),kind:'note',folderId:parent.id,title:(title.trim()||'New page').slice(0,160),blocks:[{id:uuid(),type:'text',text:'',position:0,editedAt:Date.now()}],updated:Date.now(),lifecycleUpdatedAt:Date.now()};core.notes().unshift(n);expanded.add(parent.id);if(!insertPageLink(n.id,range)){core.remove(n.id);return}core.cancelSave();await core.save(n);if(core.activeId()===parent.id)await core.save(core.current());renderList();return n}

  function insertPageLink(id,range=mentionRange){const target=items().find(x=>x.id===id&&!x.trashedAt);if(!target||!range||!core.editor.contains(range.commonAncestorContainer))return false;range.deleteContents();const a=document.createElement('a');a.dataset.pageId=id;a.href='#page='+id;a.textContent=target.title||'Untitled';range.insertNode(a);range.setStartAfter(a);range.collapse(true);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);closeMentions();(a.closest('[contenteditable=true]')||core.editor).dispatchEvent(new InputEvent('input',{bubbles:true}));renderPageRelations();return true}
  function updateMentions(e={}){const selection=getSelection();if(e.isComposing)return;if(!selection?.isCollapsed||!selection.rangeCount)return closeMentions();const r=selection.getRangeAt(0).cloneRange();let node=r.startContainer;if(node.nodeType===1&&r.startOffset>0){node=node.childNodes[r.startOffset-1];while(node?.lastChild)node=node.lastChild;if(node?.nodeType===3){r.setStart(node,node.textContent.length);r.collapse(true)}}if(node?.nodeType!==3||node.parentElement.closest('code,[data-type=code],a,span[data-thread-mention]'))return closeMentions();const match=node.textContent.slice(0,r.startOffset).match(/(?:^|\s)@([^@\n]{0,60})$/);if(!match)return closeMentions();const start=r.startOffset-match[1].length-1;mentionRange=r.cloneRange();mentionRange.setStart(node,start);mentions.replaceChildren();mentionIndex=0;const query=match[1].trim();if(/^threads-/i.test(query)){if(!isNormalPage(core.note()))return closeMentions();const name=query.slice(8).toLowerCase();for(const thread of orderedThreads().filter(n=>(n.title||'Untitled').toLowerCase().includes(name)).slice(0,12)){const b=button('✓ Tick '+(thread.title||'Untitled')+' today',()=>insertThreadMention(thread));b.setAttribute('role','option');b.onmousedown=e=>e.preventDefault();mentions.append(b)}}else{const candidates=items().filter(n=>n.id!==core.activeId()&&!n.trashedAt&&!isThreadPage(n)&&!monthIndexOf(n)&&(n.title||'Untitled').toLowerCase().includes(match[1].toLowerCase())).slice(0,12);for(const keyword of ['today','yesterday','tomorrow','now'].filter(k=>k.startsWith(match[1].toLowerCase()))){const b=button('@'+keyword,()=>insertDateMention(keyword));b.setAttribute('role','option');b.onmousedown=e=>e.preventDefault();mentions.append(b)}for(const n of candidates){const b=button(n.title||'Untitled',()=>insertPageLink(n.id));b.setAttribute('role','option');b.onmousedown=e=>e.preventDefault();mentions.append(b)}if(query&&!['today','yesterday','tomorrow','now'].includes(query.toLowerCase())){const title=query.toLowerCase()==='newpage'?'New page':query,b=button('Create subpage “'+title+'”',()=>createMentionSubpage(title));b.setAttribute('role','option');b.onmousedown=e=>e.preventDefault();if(query.toLowerCase()==='newpage')mentions.prepend(b);else mentions.append(b)}}if(!mentions.children.length)return closeMentions();mentions.firstChild.setAttribute('aria-selected','true');mentions.hidden=false;positionMentions()};
  function positionMentions(){if(mentions.hidden||!mentionRange)return;const rect=mentionRange.getBoundingClientRect(),viewport=window.visualViewport,left=viewport?.offsetLeft||0,top=viewport?.offsetTop||0,width=viewport?.width||innerWidth,height=viewport?.height||innerHeight;mentions.style.maxHeight=Math.max(44,Math.min(240,height-16))+'px';const menuHeight=mentions.offsetHeight,below=rect.bottom+6;mentions.style.left=Math.max(left+8,Math.min(rect.left,left+width-mentions.offsetWidth-8))+'px';mentions.style.top=Math.max(top+8,Math.min(below+menuHeight>top+height-8?rect.top-menuHeight-6:below,top+height-menuHeight-8))+'px'}
  core.editor.addEventListener('input',updateMentions);core.editor.addEventListener('editor-restored',updateMentions);core.editor.addEventListener('compositionend',()=>requestAnimationFrame(()=>updateMentions()));
  core.editor.addEventListener('beforeinput',e=>{if(e.isComposing||mentions.hidden)return;if(e.inputType==='insertText'&&e.data===' '&&mentionRange){const query=mentionRange.toString().slice(9).trim().toLowerCase(),matches=orderedThreads().filter(n=>(n.title||'Untitled').toLowerCase()===query);if(mentionRange.toString().toLowerCase().startsWith('@threads-')&&matches.length===1){e.preventDefault();e.stopImmediatePropagation();insertThreadMention(matches[0]);return}}if(['insertParagraph','insertLineBreak'].includes(e.inputType)){e.preventDefault();e.stopImmediatePropagation();mentions.children[mentionIndex]?.click()}},true);
  mentions.addEventListener('pointerdown',e=>{if(e.target.closest('button'))e.preventDefault()});
  window.visualViewport?.addEventListener('resize',positionMentions);window.visualViewport?.addEventListener('scroll',positionMentions);window.addEventListener('resize',positionMentions);
  document.addEventListener('keydown',e=>{if(mentions.hidden||!core.editor.contains(e.target))return;if(e.key==='Escape'){e.preventDefault();closeMentions()}else if(['ArrowDown','ArrowUp','Enter'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const options=[...mentions.children];if(e.key==='Enter')options[mentionIndex]?.click();else{mentionIndex=(mentionIndex+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((b,i)=>b.setAttribute('aria-selected',String(i===mentionIndex)));options[mentionIndex]?.scrollIntoView({block:'nearest'})}}},true);
  core.editor.addEventListener('click',e=>{const a=e.target.closest('a[data-page-id]');if(!a)return;e.preventDefault();const n=items().find(n=>n.id===a.dataset.pageId);if(n&&!n.trashedAt)openNote(n.id);else toast('This page is unavailable or in the recycle bin')});
  document.addEventListener('mousedown',e=>{if(!mentions.contains(e.target)&&!core.editor.contains(e.target))closeMentions()});

  let lastThreadDay=dateKey();setInterval(()=>{const day=dateKey();if(day!==lastThreadDay){lastThreadDay=day;renderThreadToday(core.note());if(view==='threads'&&!$('#home-view').hidden)renderThreads()}},60000);
  setLoading(true);

  return {restoreLocation,addMovie,setMovieWatched,movieLink,moviePreview,reorderThread,orderedThreads,createMentionSubpage,createThread,toggleThread,dateKey,insertDateMention,createSubpage,movePage:async(id,parentId)=>{const n=items().find(x=>x.id===id);if(!n||parentId&&(!core.notes().some(x=>x.id===parentId&&!x.deleted&&!x.trashedAt)||descendant(parentId,id)))return false;if(parentId)expanded.add(parentId);await lifecycle(n,{folderId:parentId});return true},renderPageRelations,insertPageLink,renderList,renderHome,showHome,openNote,createNote,navigate,lifecycle,createFolder,permanentDelete,visibleNotes,folders,setLoading};
